describe('REQ-001: Term availability enforcement', () => {
    test('term availability — winter-only subject rejected in summer', () => {
        const insolvency = findSubject('16'); // Winter only
        const errors = Engine.validateSemester([], insolvency, 'summer2026');
        assert.ok(errors.some(e => e.includes('not offered in Summer')));
    });

    test('term availability — summer-only subject rejected in winter', () => {
        const conflictOfLaws = findSubject('18'); // Summer only
        const errors = Engine.validateSemester([], conflictOfLaws, 'winter2026');
        assert.ok(errors.some(e => e.includes('not offered in Winter')));
    });

    test('term availability — dual-term subject accepted in both', () => {
        const foundations = findSubject('01'); // Winter + Summer
        assert.deepEqual(Engine.validateSemester([], foundations, 'winter2026'), []);
        assert.deepEqual(Engine.validateSemester([], foundations, 'summer2026'), []);
    });

    test('term availability — isAvailableInTerm true for completed regardless of terms', () => {
        const insolvency = findSubject('16'); // Winter only
        assert.equal(Engine.isAvailableInTerm(insolvency, 'completed'), true);
    });
});

describe('REQ-002: Semester capacity limit', () => {
    test('semester capacity — 5th subject rejected', () => {
        const four = [findSubject('01'), findSubject('02'), findSubject('03'), findSubject('04')];
        const fifth = findSubject('05');
        const errors = Engine.validateSemester(four, fifth, 'winter2026');
        assert.ok(errors.some(e => e.includes('Maximum of 4')));
    });

    test('semester capacity — 4th subject accepted (no capacity error)', () => {
        const three = [findSubject('01'), findSubject('02'), findSubject('03')];
        const fourth = findSubject('04');
        const errors = Engine.validateSemester(three, fourth, 'winter2026');
        assert.ok(!errors.some(e => e.includes('Maximum of 4')));
    });
});

