describe('REQ-005 / REQ-006: Clash detection scoping', () => {
    test('lecture clash — same lecture day flagged both ways', () => {
        // Criminal Law & Procedure (02) and Contracts (04) both lecture Tuesday
        const s1 = findSubject('02');
        const s2 = findSubject('04');
        const clashes = Engine.getClashingSubjects([s1, s2], 'winter2099', currentTerm);
        assert.ok(clashes[s1.id]?.some(w => w.includes('Lecture clash on Tuesday')));
        assert.ok(clashes[s2.id]?.some(w => w.includes('Lecture clash on Tuesday')));
    });

    test('lecture clash — different lecture days not flagged', () => {
        const s1 = findSubject('01'); // Wednesday
        const s2 = findSubject('03'); // Monday
        const clashes = Engine.getClashingSubjects([s1, s2], 'winter2099', currentTerm);
        assert.equal(clashes[s1.id], undefined);
        assert.equal(clashes[s2.id], undefined);
    });

    test('lecture clash — checked for a semester that is NOT currentTerm', () => {
        // Proves REQ-005's "all semesters" claim: pass a semesterId far from currentTerm.
        const s1 = findSubject('02');
        const s2 = findSubject('04');
        const clashes = Engine.getClashingSubjects([s1, s2], 'summer2035', currentTerm);
        assert.ok(clashes[s1.id]?.some(w => w.includes('Lecture clash')));
    });

    // NOTE: as of 2026-09-26, subjects.js has all `exam` fields set to `null`
    // pending LPAB's next timetable publication (see subjects.js's own header
    // comment). These two tests therefore use synthetic subject-shaped objects
    // (cloned from real subjects, with only `exam`/`id` overridden) rather than
    // depending on which two real subjects happen to share an exam time today
    // — that fixture assumption is not stable across data updates, exactly the
    // kind of drift this codebase's own data-update procedure can trigger.
    test('exam clash — flagged when semesterId equals currentTerm', () => {
        const s1 = { ...findSubject('09'), exam: '3 Sep 2026, 1.45 pm' };
        const s2 = { ...findSubject('13'), exam: '3 Sep 2026, 1.45 pm' };
        const clashes = Engine.getClashingSubjects([s1, s2], currentTerm, currentTerm);
        assert.ok(clashes[s1.id]?.some(w => w.includes('Exam clash')));
        assert.ok(clashes[s2.id]?.some(w => w.includes('Exam clash')));
    });

    test('exam clash — a future term shows a possible clash, never a confirmed one (REQ-006 condition d)', () => {
        // Same pair evaluated as if placed in a future term. Exam dates in
        // subjects.js belong to the current term only, so they can't confirm
        // a clash elsewhere — but a pair that clashes in a published timetable
        // is flagged as a possible clash (see BUGS.md BUG-001, fixed).
        const s1 = { ...findSubject('09'), exam: '3 Sep 2026, 1.45 pm' };
        const s2 = { ...findSubject('13'), exam: '3 Sep 2026, 1.45 pm' };
        const clashes = Engine.getClashingSubjects([s1, s2], 'winter2030', currentTerm);
        assert.ok(!clashes[s1.id]?.some(w => w.startsWith('Exam clash')),
            'REQ-006(d): no confirmed exam clash outside the current term');
        assert.ok(clashes[s1.id]?.includes(POSSIBLE_EXAM_CLASH),
            'REQ-006(d): a pair that has clashed before is flagged as a possible clash');
    });
});

describe('REQ-007 / REQ-008 / REQ-009: Exam date parsing and clash equality', () => {
    test('parseExamDate — valid format parses correctly', () => {
        const d = parseExamDate('8 Sep 2026, 9.00 am');
        assert.equal(d.getFullYear(), 2026);
        assert.equal(d.getMonth(), 8); // September = index 8
        assert.equal(d.getDate(), 8);
        assert.equal(d.getHours(), 9);
        assert.equal(d.getMinutes(), 0);
    });

    test('parseExamDate — pm conversion to 24-hour', () => {
        const d = parseExamDate('7 Sep 2026, 1.45 pm');
        assert.equal(d.getHours(), 13);
        assert.equal(d.getMinutes(), 45);
    });

    test('parseExamDate — 12 pm stays 12, 12 am becomes 0', () => {
        assert.equal(parseExamDate('1 Jan 2026, 12.00 pm').getHours(), 12);
        assert.equal(parseExamDate('1 Jan 2026, 12.00 am').getHours(), 0);
    });

    test('parseExamDate — unrecognized month returns null (documents REQ-007 condition c)', () => {
        const result = parseExamDate('8 Sept 2026, 9.00 am'); // 'Sept' not 'Sep'
        assert.equal(result, null);
    });

    test('parseExamDate — null/undefined input returns null without throwing', () => {
        assert.equal(parseExamDate(null), null);
        assert.equal(parseExamDate(undefined), null);
    });

    test('formatExamDate — round-trips a parsed date back to the original string', () => {
        const original = '7 Sep 2026, 1.45 pm';
        const roundTripped = formatExamDate(parseExamDate(original));
        assert.equal(roundTripped, original);
    });

    test('examTimesClash — exact match clashes', () => {
        assert.equal(examTimesClash('8 Sep 2026, 9.00 am', '8 Sep 2026, 9.00 am'), true);
    });

    test('examTimesClash — near-miss (15 minutes apart) does not clash', () => {
        assert.equal(examTimesClash('8 Sep 2026, 9.00 am', '8 Sep 2026, 9.15 am'), false);
    });

    test('examTimesClash — null input never clashes (REQ-009)', () => {
        assert.equal(examTimesClash(null, '8 Sep 2026, 9.00 am'), false);
        assert.equal(examTimesClash(null, null), false);
    });

    test('sortByExamDate — does not mutate the input array', () => {
        const arr = [findSubject('11'), findSubject('01')];
        const copy = [...arr];
        sortByExamDate(arr);
        assert.deepEqual(arr, copy);
    });

    test('sortByExamDate — subjects with null exam sort to the end', () => {
        const withNullExam = { ...findSubject('18'), exam: null };
        const withExam = findSubject('01');
        const sorted = sortByExamDate([withNullExam, withExam]);
        assert.equal(sorted[sorted.length - 1].exam, null);
    });
});

describe('REQ-010 / REQ-011: Progress and graduation status', () => {
    test('progress — counts compulsory and elective independently', () => {
        const plan = {
            winter2026: [findSubject('01'), findSubject('16')], // 1 compulsory (core), 1 elective
            completed: [findSubject('12')] // 1 compulsory
        };
        const progress = Engine.calculateProgress(plan);
        assert.equal(progress.compulsory.current, 2);
        assert.equal(progress.electives.current, 1);
    });

    test('progress — required thresholds are 17 and 3', () => {
        const progress = Engine.calculateProgress({});
        assert.equal(progress.compulsory.required, 17);
        assert.equal(progress.electives.required, 3);
    });

    test('graduation — not ready with 16 compulsory + 3 electives', () => {
        const coreAndCompulsory = subjects.filter(s => s.type === 'Compulsory').slice(0, 16);
        const electives = subjects.filter(s => s.type === 'Elective').slice(0, 3);
        const plan = { completed: [...coreAndCompulsory, ...electives] };
        assert.equal(Engine.calculateProgress(plan).readyToGraduate, false);
    });

    test('graduation — ready at exactly 17 compulsory + 3 electives', () => {
        const allCompulsory = subjects.filter(s => s.type === 'Compulsory'); // exactly 17 in subjects.js
        assert.equal(allCompulsory.length, 17, 'fixture assumption: subjects.js has exactly 17 Compulsory rows');
        const electives = subjects.filter(s => s.type === 'Elective').slice(0, 3);
        const plan = { completed: [...allCompulsory, ...electives] };
        assert.equal(Engine.calculateProgress(plan).readyToGraduate, true);
    });

    test('graduation — still ready with more than 3 electives (>= not ==)', () => {
        const allCompulsory = subjects.filter(s => s.type === 'Compulsory');
        const electives = subjects.filter(s => s.type === 'Elective').slice(0, 5);
        const plan = { completed: [...allCompulsory, ...electives] };
        assert.equal(Engine.calculateProgress(plan).readyToGraduate, true);
    });
});

