describe('REQ-014: Storage failure resilience', () => {
    test('storage — loadPlan returns default when localStorage throws', async () => {
        const originalLocalStorage = globalThis.localStorage;
        globalThis.localStorage = {
            getItem() { throw new Error('simulated storage failure'); },
            setItem() { throw new Error('simulated storage failure'); },
            removeItem() { throw new Error('simulated storage failure'); }
        };
        try {
            const { loadPlan } = await import('../js/state/storage.js?cachebust=' + Date.now());
            assert.deepEqual(loadPlan(), { completed: [] });
        } finally {
            globalThis.localStorage = originalLocalStorage;
        }
    });

    test('storage — savePlan does not throw when localStorage.setItem throws', async () => {
        const originalLocalStorage = globalThis.localStorage;
        globalThis.localStorage = {
            getItem() { return null; },
            setItem() { throw new Error('quota exceeded'); },
            removeItem() {}
        };
        try {
            const { savePlan } = await import('../js/state/storage.js?cachebust=' + Date.now());
            assert.doesNotThrow(() => savePlan({ completed: [] }));
        } finally {
            globalThis.localStorage = originalLocalStorage;
        }
    });

    test('storage — loadHiddenSubjects returns [] on malformed JSON', async () => {
        const originalLocalStorage = globalThis.localStorage;
        globalThis.localStorage = {
            getItem() { return '{not valid json'; },
            setItem() {},
            removeItem() {}
        };
        try {
            const { loadHiddenSubjects } = await import('../js/state/storage.js?cachebust=' + Date.now());
            assert.deepEqual(loadHiddenSubjects(), []);
        } finally {
            globalThis.localStorage = originalLocalStorage;
        }
    });
});

