describe('Boundary: generateTermSequence', () => {
    test('generateTermSequence — alternates winter/summer starting from currentTerm season', () => {
        const terms = generateTermSequence('winter2026');
        assert.equal(terms[0], 'winter2026');
        assert.equal(terms[1], 'summer2026');
        assert.equal(terms[2], 'winter2027');
    });

    test('generateTermSequence — starting from summer increments year only after summer->winter', () => {
        const terms = generateTermSequence('summer2026');
        assert.equal(terms[0], 'summer2026');
        assert.equal(terms[1], 'winter2027');
    });

    test('generateTermSequence — produces exactly 8 terms matching SUGGESTED_PATHWAY length', () => {
        const terms = generateTermSequence(currentTerm);
        assert.equal(terms.length, 8);
        assert.equal(terms.length, SUGGESTED_PATHWAY.length);
    });
});

